<template>
<div class="health-shell">
 <aside class="health-sidebar"><a class="health-brand" href="/health-home"><span class="brand-mark"><HealthIcon name="health"/></span><span>MyHealthy<small>慢病健康管理</small></span></a><p class="nav-caption">健康工作空间</p><nav aria-label="健康主导航"><button v-for="n in navItems" :key="n.path" :class="{active:n.path==='/health-home'}" :aria-current="n.path==='/health-home'?'page':undefined" @click="router.push(n.path)"><HealthIcon :name="n.icon"/>{{n.label}}</button></nav><div class="sidebar-note"><HealthIcon name="shield"/><strong>教学演示环境</strong><p>使用合成数据探索健康管理流程。</p></div><button v-if="isDoctor" class="sidebar-extra" @click="router.push('/health-practitioner')">健康师工作台 <HealthIcon name="arrow"/></button><button v-if="canManage" class="sidebar-extra" @click="router.push('/index')">管理工作台 <HealthIcon name="arrow"/></button><button class="logout" @click="logout">退出登录</button></aside>
 <div class="health-workspace"><header class="workspace-header"><span>个人健康中心 <span class="header-divider">/</span> <strong>健康总览</strong></span><span class="header-right"><span class="environment-dot"></span>课程演示 <span class="user-avatar">健</span><button class="header-logout" @click="logout">退出</button></span></header>
 <main class="dashboard-content"><section class="page-intro"><div><p class="eyebrow">{{displayDate}}</p><h1>今天，也关注一下健康</h1><p>查看最新测量，记录每一次变化。</p></div><el-button type="primary" size="large" @click="router.push('/simulator/pressure')"><HealthIcon name="health"/> 开始一次测量</el-button></section>
 <section class="metrics-grid" aria-label="最新健康指标"><article v-for="item in indicators" :key="item.kind" class="metric-card" :class="item.kind"><div class="metric-heading"><span class="metric-icon"><HealthIcon :name="metricIcons[item.kind]"/></span><span>{{item.name}}</span><span class="metric-label">最新记录</span></div><div class="metric-value">{{valueOnly(item.kind)}}<small>{{units[item.kind]}}</small></div><div class="metric-bottom"><span>教学模拟数据</span><button @click="router.push('/health-records/'+item.module)" :aria-label="'查看'+item.name+'记录'">查看记录 <HealthIcon name="arrow"/></button></div></article></section>
 <div class="dashboard-grid"><section class="surface trend-panel"><div class="section-heading"><div><p class="eyebrow">HEALTH TRENDS</p><h2>最近10天的健康趋势</h2></div><span class="quiet-label">基于已保存的测量</span></div><el-radio-group v-model="selected" @change="loadTrend" aria-label="健康趋势筛选"><el-radio-button value="all">全部指标</el-radio-button><el-radio-button v-for="i in indicators" :key="i.kind" :value="i.kind">{{i.name}}</el-radio-button></el-radio-group><p class="trend-note">{{selected === 'all' ? '四类指标使用独立纵轴与单位，点击曲线可查看单项记录。' : '当前指标的已保存记录；选择全部指标返回总览。'}}</p><el-alert v-if="trendError" :title="trendError" type="error" :closable="false"/><section ref="chartEl" class="trend-chart" :style="{height:selected === 'all' ? (compactTrend ? '1000px' : '520px') : '300px'}" role="img" :aria-label="chartDescription"></section><el-empty v-if="!trend.length && !trendError" description="最近10天暂无测量记录"/><template v-if="selected !== 'all'"><h3>{{selectedName}}测量记录</h3><el-table :data="currentRecords" stripe max-height="280" empty-text="最近10天暂无该项记录"><el-table-column prop="measure_time" label="测量时间" min-width="170" :formatter="row=>String(row.measure_time||'').replace('T',' ')"/><el-table-column v-for="column in recordColumns" :key="column.key" :prop="column.key" :label="column.label" min-width="130" :formatter="row=>column.key==='meal_state'?(row[column.key]==='fasting'?'空腹':'餐后'):row[column.key]"/></el-table></template></section>
 <aside class="care-column"><section class="care-card"><span class="care-icon"><HealthIcon name="heart"/></span><p class="eyebrow">持续记录 便于回顾</p><h2>把每次测量<br/>连成健康档案</h2><p>数值只是记录的开始。结合用药、随访与健康师建议，更完整地了解变化。</p><button @click="router.push('/health-records/tuser')">查看个人档案 <HealthIcon name="arrow"/></button><svg class="care-wave" viewBox="0 0 300 70" aria-hidden="true"><path d="M0 44h45l15-15 16 32 27-55 20 47 16-14h30l15-12 18 25 14-8h84" fill="none" stroke="currentColor" stroke-width="2"/></svg></section><section class="surface report-card"><HealthIcon name="file"/><h3>教学健康报告</h3><p>汇总四类最新指标，生成本地规则草稿并交由健康师核对。</p><el-button @click="generate">生成教学报告</el-button></section></aside></div>
 <section class="surface services-panel"><div class="section-heading"><div><p class="eyebrow">YOUR HEALTH SERVICES</p><h2>常用健康服务</h2></div></div><div class="services-grid"><button v-for="m in modules" :key="m.module" @click="router.push('/health-records/'+m.module)"><span class="service-symbol"><HealthIcon :name="m.module==='sports'?'pulse':m.module==='device'?'heart':'file'"/></span><span>{{m.label}}<small>查看与管理</small></span><HealthIcon name="arrow"/></button><button @click="router.push('/simulator/sports')"><span class="service-symbol"><HealthIcon name="pulse"/></span><span>运动手表<small>模拟并保存步数</small></span><HealthIcon name="arrow"/></button></div></section>
 <section class="surface alerts-panel"><div class="section-heading"><h2>异常提示</h2><span class="quiet-label">仅供教学参考</span></div><p class="empty-note" v-if="!data.alerts?.length"><HealthIcon name="shield"/> 暂无异常提示，请保持记录。</p><el-alert v-for="a in data.alerts" :key="a.id" :title="a.message" type="warning" :closable="false"/></section><footer class="dashboard-footer">MyHealthy 课程项目<span>模拟数据不用于医学诊断</span></footer></main></div>
</div></template>
<script setup>
import HealthIcon from '@/components/HealthIcon.vue'
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import * as echarts from 'echarts'
import {call} from '@/api/health'
import useUserStore from '@/store/modules/user'
const isDoctor=useUserStore().roles.includes('healthyperson');const canManage=useUserStore().roles.some(r=>['admin','healthadmin'].includes(r));
const router=useRouter(),data=ref({}),selected=ref('all'),compactTrend=ref(false),trend=ref([]),trendRows=ref({}),trendError=ref(''),chartEl=ref();let chart,resizeObserver;let requestSequence=0,disposed=false
const indicators=[{kind:'pressure',module:'measurement',name:'血压'},{kind:'glucose',module:'myblood',name:'血糖'},{kind:'lipid',module:'lipid',name:'血脂'},{kind:'ecg',module:'heart',name:'心电图'}]
const metricIcons={pressure:'pulse',glucose:'drop',lipid:'layers',ecg:'heart'}
const units={pressure:'mmHg',glucose:'mmol/L',lipid:'mmol/L',ecg:'bpm'}
const displayDate=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())
const navItems=[{label:'健康总览',path:'/health-home',icon:'home'},{label:'测量记录',path:'/health-records/measurement',icon:'chart'},{label:'健康档案',path:'/health-records/tuser',icon:'file'},{label:'健康报告',path:'/health-records/report',icon:'file'},{label:'在线咨询',path:'/health-consultation',icon:'chat'},{label:'AI健康助手',path:'/health-ai',icon:'pulse'},{label:'健康知识',path:'/health-knowledge',icon:'book'},{label:'健康商城',path:'/health-shop',icon:'shop'}]
const modules=[{module:'tuser',label:'个人档案'},{module:'medichine',label:'用药记录'},{module:'record',label:'随访记录'},{module:'report',label:'健康报告'},{module:'device',label:'设备管理'},{module:'plan',label:'健康计划'},{module:'sports',label:'运动记录'}]
function latest(k){const d=data.value[k];if(!d)return '暂无记录';return k==='pressure'?`${d.systolic}/${d.diastolic} mmHg`:k==='glucose'?`${d.glucose} mmol/L`:k==='lipid'?`${d.total_cholesterol} mmol/L`:`${d.heart_rate} bpm`}
const metricSettings = {
 pressure:{field:'systolic',label:'收缩压',unit:'mmHg',color:'#148978',columns:[{key:'systolic',label:'收缩压 mmHg'},{key:'diastolic',label:'舒张压 mmHg'},{key:'heart_rate',label:'心率 bpm'}]},
 glucose:{field:'glucose',label:'血糖',unit:'mmol/L',color:'#cb7b2f',columns:[{key:'glucose',label:'血糖 mmol/L'},{key:'meal_state',label:'空腹或餐后'}]},
 lipid:{field:'total_cholesterol',label:'总胆固醇',unit:'mmol/L',color:'#7464b8',columns:[{key:'total_cholesterol',label:'总胆固醇 mmol/L'},{key:'triglycerides',label:'甘油三酯 mmol/L'},{key:'hdl',label:'HDL mmol/L'},{key:'ldl',label:'LDL mmol/L'}]},
 ecg:{field:'heart_rate',label:'心率',unit:'bpm',color:'#447eb3',columns:[{key:'heart_rate',label:'心率 bpm'},{key:'duration_seconds',label:'检测时长 秒'}]}
}
const selectedName=computed(()=>indicators.find(i=>i.kind===selected.value)?.name||'全部指标')
const currentRecords=computed(()=>trendRows.value[selected.value]||[])
const recordColumns=computed(()=>metricSettings[selected.value]?.columns||[])
const chartDescription=computed(()=>selected.value==='all'
 ? '最近10天四类趋势总览：收缩压mmHg、血糖mmol/L、总胆固醇mmol/L、心率bpm，各自独立纵轴'
 : `${selectedName.value}最近10天趋势，${metricSettings[selected.value]?.unit}，${currentRecords.value.length}条已保存记录`)
function selectMetric(name){const item=indicators.find(i=>i.name===name);if(item){selected.value=item.kind;loadTrend()}}
async function loadTrend(){
 const sequence=++requestSequence,chosen=selected.value
 const visible=chosen==='all'?indicators:indicators.filter(i=>i.kind===chosen)
 trendError.value=''
 try{
  const responses=await Promise.all(visible.map(i=>call('workflow/trends','get',null,{kind:i.kind})))
  if(sequence!==requestSequence||disposed)return
  const rows={...trendRows.value}
  visible.forEach((item,index)=>rows[item.kind]=responses[index].data||[])
  trendRows.value=rows;trend.value=visible.flatMap(item=>rows[item.kind])
  compactTrend.value=chartEl.value.clientWidth<560;await nextTick();if(disposed)return
  if(!chart){
   chart=echarts.init(chartEl.value)
   chart.on('click',event=>selectMetric(event.seriesName))
   chart.on('legendselectchanged',event=>selectMetric(event.name))
  }
  const all=chosen==='all',compact=compactTrend.value
  const titles=visible.map((item,index)=>({text:`${item.name} · ${metricSettings[item.kind].label} (${metricSettings[item.kind].unit})`,left:all?(compact?'8%':(index%2===0?'5%':'55%')):'5%',top:all?(compact?(index*24+5)+'%':(index<2?'8%':'55%')):'2%',textStyle:{fontSize:12,fontWeight:'normal'}}))
  const grids=visible.map((item,index)=>all?(compact?{left:'20%',right:'8%',top:(index*24+10)+'%',height:'12%',containLabel:false}:{left:index%2===0?'9%':'59%',right:index%2===0?'56%':'6%',top:index<2?'18%':'65%',height:'25%',containLabel:false}):{left:65,right:25,top:55,bottom:40})
  const axes=visible.map((item,index)=>({type:'time',gridIndex:index,axisLabel:{hideOverlap:true,fontSize:10},splitNumber:3}))
  const yAxes=visible.map((item,index)=>({type:'value',gridIndex:index,scale:true,axisLabel:{fontSize:10},splitNumber:3,splitLine:{lineStyle:{color:'#e2eae8'}}}))
  const series=visible.map((item,index)=>({name:item.name,type:'line',xAxisIndex:index,yAxisIndex:index,showSymbol:true,symbolSize:5,connectNulls:false,smooth:false,
   itemStyle:{color:metricSettings[item.kind].color},lineStyle:{width:2},
   data:rows[item.kind].map(row=>[new Date(row.measure_time).getTime(),row[metricSettings[item.kind].field]])}))
  chart.setOption({title:titles,legend:all?{top:0,data:visible.map(i=>i.name)}:undefined,tooltip:{trigger:'axis'},grid:grids,xAxis:axes,yAxis:yAxes,series},true)
  chart.resize()
 }catch(error){
  if(sequence===requestSequence&&!disposed){trendError.value='趋势加载失败，请选择指标重试。';trend.value=[];chart?.clear();ElMessage.error(trendError.value)}
 }
}
function valueOnly(k){const value=latest(k);return value==='暂无记录'?'—':value.replace(/ (mmHg|mmol\/L|bpm)$/,'')}
async function generate(){await call('workflow/report','post');ElMessage.success('已生成本地规则汇总报告，未调用AI');router.push('/health-records/report')}
async function logout(){await useUserStore().logOut();router.push('/login')}
function resize(){const compact=chartEl.value?.clientWidth<560;if(compact!==compactTrend.value){compactTrend.value=compact;if(chart)loadTrend()}else chart?.resize()}
onMounted(async()=>{window.addEventListener('resize',resize);resizeObserver=new ResizeObserver(resize);resizeObserver.observe(chartEl.value);try{data.value=(await call('workflow/dashboard')).data;await loadTrend()}catch(error){ElMessage.error('首页指标加载失败，请刷新重试')}})
onBeforeUnmount(()=>{disposed=true;++requestSequence;window.removeEventListener('resize',resize);resizeObserver?.disconnect();chart?.dispose()})
</script>
<style scoped>
