owrap}.metric-bottom svg{width:12px;height:12px;margin-left:2px}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:22px;align-items:start;margin-bottom:24px}.surface{background:#fff;border:1px solid var(--line);border-radius:12px;padding:23px;min-width:0}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:23px}.section-heading h2{font-size:17px;margin:0;font-weight:650;line-height:1.5}.quiet-label{font-size:10px;color:#819287}.trend-note{font-size:11px;color:#83938b;line-height:1.8;margin:15px 0 0}.trend-chart{width:100%;min-width:0}.trend-panel :deep(.el-radio-button__inner){font-size:11px;padding:9px 13px;box-shadow:none!important;border:0;background:#f3f7f3;color:#6a7c70}.trend-panel :deep(.el-radio-button.is-active .el-radio-button__inner){background:#e4efe5;color:#2c6a47}.care-column{display:grid;gap:20px}.care-card{background:#e8f0e4;border:1px solid #dfe8d9;border-radius:12px;padding:25px;position:relative;overflow:hidden}.care-icon{display:grid;place-items:center;width:40px;height:40px;background:#d8e7d1;color:#63825a;border-radius:11px;margin-bottom:25px}.care-card .eyebrow{letter-spacing:2px}.care-card h2{font-size:23px;line-height:1.6;font-weight:600;margin:12px 0;color:#31523b}.care-card p:not(.eyebrow){font-size:12px;line-height:1.9;color:#6c816a}.care-card button{display:flex;gap:10px;align-items:center;background:#fff;border:1px solid #d7e3d0;border-radius:8px;padding:11px 14px;font:inherit;font-size:11px;color:#42663e;cursor:pointer;margin:22px 0 40px}.care-card button svg{width:15px}.care-wave{position:absolute;bottom:10px;left:0;width:100%;height:55px;color:#bed2b2}.report-card>svg{color:#6e8c7c;margin-bottom:5px}.report-card h3{font-size:14px;margin:9px 0}.report-card p{font-size:12px;color:#7e8f84;line-height:1.9}.report-card .el-button{width:100%;font-size:12px;min-height:38px;color:#47745d;border-color:#dce7df}.services-panel{margin-bottom:24px}.services-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.services-grid button{display:flex;align-items:center;gap:12px;padding:15px;background:#fff;border:1px solid #e8eee7;border-radius:9px;text-align:left;cursor:pointer;min-height:77px;color:#375743;font:inherit;font-size:12px;transition:background .18s,border-color .18s}.services-grid button:hover{background:#f4f8f1;border-color:#bed0bb}.service-symbol{background:#f2f6ee;color:#82966d;padding:9px;border-radius:9px;display:flex}.service-symbol svg{width:18px;height:18px}.services-grid small{display:block;font-size:10px;color:#9aa593;margin-top:7px}.services-grid button>svg{width:13px;margin-left:auto;color:#a4b49f}.alerts-panel{margin-bottom:22px}.alerts-panel .section-heading{margin-bottom:15px}.empty-note{font-size:12px;color:#7a9180;display:flex;align-items:center;gap:10px;margin:0;padding:9px 0}.empty-note svg{width:18px;color:#82a080}.dashboard-footer{display:flex;justify-content:space-between;color:#9aa69b;font-size:10px;padding:6px 0 12px}.el-alert{margin-bottom:10px}button:focus-visible,a:focus-visible{outline:3px solid #176b52;outline-offset:3px}
